    #[test]
    fn cid_width_tables_resolve_mixed_forms_and_boundary_codes() {
        let mut pdf = PdfDocument::new();
        let first = pdf.add_object(Object::Integer(0));
        let last = pdf.add_object(Object::Integer(65535));
        let width = pdf.add_object(Object::Real(400.5));
        let array = pdf.add_object(Object::Array(vec![Object::Reference(width), 500.into()]));
        let table = pdf.add_object(Object::Array(vec![
            Object::Reference(first),
            Object::Reference(array),
            Object::Reference(last),
            Object::Reference(last),
            Object::Reference(width),
            1.into(),
            1.into(),
            700.into(),
        ]));
        let (default, widths) =
            pdf_cid_widths(&pdf, &dictionary! {"W" => Object::Reference(table)}).unwrap();
        assert_eq!(default, 1000.0);
        assert_eq!(widths.len(), 3);
        assert_eq!(widths[&0], 400.5);
        assert_eq!(widths[&1], 700.0);
        assert_eq!(widths[&65535], 400.5);
    }

    #[test]
    fn cid_width_tables_reject_invalid_indirect_metadata() {
        let mut pdf = PdfDocument::new();
        let cycle = pdf.add_object(Object::Reference((1, 0)));
        let missing = Object::Reference((999, 0));
        for value in [
            Object::Integer(-1),
            Object::Integer(10001),
            Object::Real(f32::NAN),
            Object::Real(f32::INFINITY),
            Object::Name(b"bad".to_vec()),
            missing.clone(),
            Object::Reference(cycle),
        ] {
            let id = pdf.add_object(value);
            assert!(pdf_cid_widths(&pdf, &dictionary! {"DW" => Object::Reference(id)}).is_err());
            let table = Object::Array(vec![0.into(), Object::Array(vec![Object::Reference(id)])]);
            assert!(pdf_cid_widths(&pdf, &dictionary! {"W" => table}).is_err());
        }
        for values in [
            vec![0.into()],
            vec![(-1).into(), Object::Array(vec![500.into()])],
            vec![65536.into(), Object::Array(vec![500.into()])],
            vec![Object::Real(1.0), Object::Array(vec![500.into()])],
            vec![0.into(), Object::Array(vec![])],
            vec![65535.into(), Object::Array(vec![500.into(), 600.into()])],
            vec![3.into(), 2.into(), 500.into()],
            vec![0.into(), 65536.into(), 500.into()],
            vec![0.into(), 1.into()],
            vec![0.into(), Object::Real(1.0), 500.into()],
            vec![missing.clone(), Object::Array(vec![500.into()])],
            vec![0.into(), missing.clone()],
            vec![0.into(), 1.into(), missing.clone()],
            vec![Object::Reference(cycle), 1.into(), 500.into()],
        ] {
            let id = pdf.add_object(Object::Array(values));
            assert!(pdf_cid_widths(&pdf, &dictionary! {"W" => Object::Reference(id)}).is_err());
        }
        for table in [missing, Object::Reference(cycle), Object::Integer(1)] {
            assert!(pdf_cid_widths(&pdf, &dictionary! {"W" => table}).is_err());
        }
    }

    #[test]
    fn cid_width_table_work_limit_counts_overwritten_ranges() {
        let pdf = PdfDocument::new();
        let mut values = Vec::new();
        for _ in 0..15 {
            values.extend([0.into(), 65535.into(), 500.into()]);
        }
        values.extend([0.into(), 16959.into(), 600.into()]);
        let (_, widths) =
            pdf_cid_widths(&pdf, &dictionary! {"W" => Object::Array(values.clone())}).unwrap();
        assert_eq!(widths.len(), 65536);
        assert_eq!(widths[&0], 600.0);
        assert_eq!(widths[&65535], 500.0);
        values.extend([0.into(), Object::Array(vec![500.into()])]);
        assert!(matches!(
            pdf_cid_widths(&pdf, &dictionary! {"W" => Object::Array(values)}),
            Err(OfdError::Limit(_))
        ));
    }

    #[test]
    fn imports_simple_truetype_font_and_reuses_embedded_resource() {
        let font_bytes = include_bytes!("../tests/fixtures/dejavu-sans.ttf");
        let source = text_pdf_with_widths(
            b"BT /F1 12 Tf 10 20 Td (AB) Tj ET BT /F1 12 Tf 10 40 Td (AB) Tj ET",
            b"DejaVuSans",
            Some((b'A', &[600.0, 600.0])),
        );
        let mut pdf = PdfDocument::load_mem(&source).unwrap();
        let font_file = pdf.add_object(Object::Stream(lopdf::Stream::new(
            dictionary! {"Length1" => font_bytes.len() as i64},
            font_bytes.to_vec(),
        )));
        let descriptor = pdf.add_object(Object::Dictionary(dictionary! {
            "Type" => Object::Name(b"FontDescriptor".to_vec()),
            "FontName" => Object::Name(b"DejaVuSans".to_vec()),
            "FontFile2" => Object::Reference(font_file),
        }));
        let font = pdf.get_object_mut((5, 0)).unwrap().as_dict_mut().unwrap();
        font.set("Subtype", Object::Name(b"TrueType".to_vec()));
        font.set("FontDescriptor", Object::Reference(descriptor));
        let mut bytes = Vec::new();
        pdf.save_to(&mut bytes).unwrap();

        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["AB", "AB"]);
        let fonts = document.fonts().unwrap();
        let embedded: Vec<_> = fonts
            .iter()
            .enumerate()
            .filter(|(_, font)| font.embedded_path.is_some())
            .collect();
        assert_eq!(embedded.len(), 1);
        assert_eq!(embedded[0].1.font_name, "DejaVu Sans");
        assert_eq!(document.font_data(embedded[0].0).unwrap(), font_bytes);
        for object in document.page_text_objects(0).unwrap() {
            assert_eq!(object.font_id.as_deref(), Some(embedded[0].1.id.as_str()));
        }
        assert!(document.validate_references().unwrap().is_empty());
        assert!(document
            .page_svg(0)
            .unwrap()
            .contains("font-family=\"ofd-embedded-font-"));
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["AB", "AB"]);
        assert_eq!(reopened.font_data(embedded[0].0).unwrap(), font_bytes);

        let mut custom_encoding = pdf.clone();
        custom_encoding
            .get_object_mut((5, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap()
            .set("Encoding", Object::Name(b"UnsupportedEncoding".to_vec()));
        let mut bytes = Vec::new();
        custom_encoding.save_to(&mut bytes).unwrap();
        assert!(OfdDocument::from_pdf_bytes(&bytes).is_err());

        let mut no_embedding = pdf;
        no_embedding
            .get_object_mut(descriptor)
            .unwrap()
            .as_dict_mut()
            .unwrap()
            .remove(b"FontFile2");
        let mut bytes = Vec::new();
        no_embedding.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["AB", "AB"]);
        assert!(document
            .fonts()
            .unwrap()
            .iter()
            .all(|font| font.embedded_path.is_none()));
        assert!(document.page_text_objects(0).unwrap()[0]
            .cg_transforms
            .is_empty());

        let source = text_pdf_with_widths(
            b"BT /F1 12 Tf 10 20 Td (\x8e) Tj ET",
            b"DejaVuSans",
            Some((0x8e, &[600.0])),
        );
        let mut mac_roman = PdfDocument::load_mem(&source).unwrap();
        let font_file = mac_roman.add_object(Object::Stream(lopdf::Stream::new(
            dictionary! {"Length1" => font_bytes.len() as i64},
            font_bytes.to_vec(),
        )));
        let descriptor = mac_roman.add_object(Object::Dictionary(dictionary! {
            "Type" => Object::Name(b"FontDescriptor".to_vec()),
            "FontName" => Object::Name(b"DejaVuSans".to_vec()),
            "FontFile2" => Object::Reference(font_file),
        }));
        let font = mac_roman
            .get_object_mut((5, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap();
        font.set("Subtype", Object::Name(b"TrueType".to_vec()));
        font.set("Encoding", Object::Name(b"MacRomanEncoding".to_vec()));
        font.set("FontDescriptor", Object::Reference(descriptor));
        let mut bytes = Vec::new();
        mac_roman.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["é"]);
        assert_eq!(
            document
                .fonts()
                .unwrap()
                .iter()
                .filter(|font| font.embedded_path.is_some())
                .count(),
            1
        );

        let mut remapped =
            PdfDocument::load_mem(include_bytes!("../tests/fixtures/type1-tounicode.pdf")).unwrap();
        let font_file = remapped.add_object(Object::Stream(lopdf::Stream::new(
            dictionary! {"Length1" => font_bytes.len() as i64},
            font_bytes.to_vec(),
        )));
        let descriptor = remapped.add_object(Object::Dictionary(dictionary! {
            "Type" => Object::Name(b"FontDescriptor".to_vec()),
            "FontName" => Object::Name(b"DejaVuSans".to_vec()),
            "FontFile2" => Object::Reference(font_file),
        }));
        let font = remapped
            .get_object_mut((5, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap();
        font.set("Subtype", Object::Name(b"TrueType".to_vec()));
        font.set("FontDescriptor", Object::Reference(descriptor));
        let mut bytes = Vec::new();
        remapped.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["中文"]);
        assert!(document
            .fonts()
            .unwrap()
            .iter()
            .any(|font| font.embedded_path.is_some()));
        assert_eq!(
            document.page_text_objects(0).unwrap()[0].cg_transforms[0].glyphs,
            [36, 37]
        );
    }

    #[test]
    fn imports_usable_embedded_pdf_font_once_for_multiple_text_runs() {
        let source = include_bytes!("../tests/fixtures/type0-identity-tounicode.pdf");
        let font_bytes = include_bytes!("../tests/fixtures/dejavu-sans.ttf");
        let mut pdf = PdfDocument::load_mem(source).unwrap();
        let font_file = pdf.add_object(Object::Stream(lopdf::Stream::new(
            dictionary! {"Length1" => font_bytes.len() as i64},
            font_bytes.to_vec(),
        )));
        let descriptor = pdf.add_object(Object::Dictionary(dictionary! {
            "Type" => Object::Name(b"FontDescriptor".to_vec()),
            "FontName" => Object::Name(b"DejaVuSans".to_vec()),
            "FontFile2" => Object::Reference(font_file),
        }));
        let face = ttf_parser::Face::parse(font_bytes, 0).unwrap();
        let mut gid_map = vec![0_u8; 6];
        gid_map[2..4].copy_from_slice(&face.glyph_index('A').unwrap().0.to_be_bytes());
        gid_map[4..6].copy_from_slice(&face.glyph_index('B').unwrap().0.to_be_bytes());
        let gid_map_id = pdf.add_object(Object::Stream(lopdf::Stream::new(
            lopdf::Dictionary::new(),
            gid_map,
        )));
        pdf.get_object_mut((7, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap()
            .set("FontDescriptor", Object::Reference(descriptor));
        pdf.get_object_mut((7, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap()
            .set("CIDToGIDMap", Object::Reference(gid_map_id));
        let cmap = pdf.get_object_mut((6, 0)).unwrap().as_stream_mut().unwrap();
        let source = std::str::from_utf8(&cmap.content).unwrap();
        cmap.content = source
            .replace("<4E2D>", "<0041>")
            .replace("<6587>", "<0042>")
            .into_bytes();
        cmap.dict.set("Length", cmap.content.len() as i64);
        let content = pdf.get_object_mut((4, 0)).unwrap().as_stream_mut().unwrap();
        content.content = b"BT /F1 12 Tf 10 20 Td [<0001> 100 <0002>] TJ ET BT /F1 12 Tf 10 40 Td [<0001> 100 <0002>] TJ ET".to_vec();
        content.dict.set("Length", content.content.len() as i64);
        let mut bytes = Vec::new();
        pdf.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["AB", "AB"]);
        let fonts = document.fonts().unwrap();
        let embedded: Vec<_> = fonts
            .iter()
            .enumerate()
            .filter(|(_, font)| font.embedded_path.is_some())
            .collect();
        assert_eq!(embedded.len(), 1);
        assert_eq!(embedded[0].1.font_name, "DejaVu Sans");
        assert_eq!(document.font_data(embedded[0].0).unwrap(), font_bytes);
        for object in document.page_text_objects(0).unwrap() {
            assert_eq!(object.font_id.as_deref(), Some(embedded[0].1.id.as_str()));
        }
        assert!(document.validate_references().unwrap().is_empty());
        assert!(document
            .page_svg(0)
            .unwrap()
            .contains("font-family=\"ofd-embedded-font-"));
        assert!(document.page_png(0, 72.0).unwrap().starts_with(b"\x89PNG"));
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["AB", "AB"]);
        assert_eq!(reopened.font_data(embedded[0].0).unwrap(), font_bytes);

        let mut mixed = pdf.clone();
        let fixture =
            PdfDocument::load_mem(include_bytes!("../tests/fixtures/type0-mixed-cmap.pdf"))
                .unwrap();
        let encoding = mixed.add_object(fixture.get_object((8, 0)).unwrap().clone());
        mixed
            .get_object_mut((5, 0))
            .unwrap()
            .as_dict_mut()
            .unwrap()
            .set("Encoding", Object::Reference(encoding));
        let stream = mixed
            .get_object_mut((6, 0))
            .unwrap()
            .as_stream_mut()
            .unwrap();
        let map = String::from_utf8(stream.get_plain_content().unwrap())
            .unwrap()
            .replace("1 begincodespacerange", "2 begincodespacerange")
            .replace("<0000> <FFFF>", "<00> <7f>\n<8140> <81ff>")
            .replace("<0001>", "<41>")
            .replace("<0002>", "<8140>");
        stream.set_plain_content(map.into_bytes());
        let stream = mixed
            .get_object_mut((4, 0))
            .unwrap()
            .as_stream_mut()
            .unwrap();
        let content = String::from_utf8(stream.get_plain_content().unwrap())
            .unwrap()
            .replace("<0001>", "<41>")
            .replace("<0002>", "<8140>");
        stream.set_plain_content(content.into_bytes());
        let mut bytes = Vec::new();
        mixed.save_to(&mut bytes).unwrap();
        let mixed = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(
            mixed.page_text_objects(0).unwrap(),
            document.page_text_objects(0).unwrap()
        );
        assert_eq!(mixed.fonts().unwrap(), document.fonts().unwrap());
        assert_eq!(mixed.font_data(embedded[0].0).unwrap(), font_bytes);
        assert_eq!(
            mixed.page_png(0, 72.0).unwrap(),
            document.page_png(0, 72.0).unwrap()
        );

        let mut opentype = pdf.clone();
        let descriptor = opentype
            .get_object_mut(descriptor)
            .unwrap()
            .as_dict_mut()
            .unwrap();
        descriptor.remove(b"FontFile2");
        descriptor.set("FontFile3", Object::Reference(font_file));
        opentype
            .get_object_mut(font_file)
            .unwrap()
            .as_stream_mut()
            .unwrap()
            .dict
            .set("Subtype", Object::Name(b"OpenType".to_vec()));
        let mut bytes = Vec::new();
        opentype.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["AB", "AB"]);
        assert_eq!(
            document
                .fonts()
                .unwrap()
                .iter()
                .filter(|font| font.embedded_path.is_some())
                .count(),
            1
        );

        let mut wrong_glyph = pdf.clone();
        wrong_glyph
            .get_object_mut(gid_map_id)
            .unwrap()
            .as_stream_mut()
            .unwrap()
            .content[3] = 0;
        let mut bytes = Vec::new();
        wrong_glyph.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert!(document
            .fonts()
            .unwrap()
            .iter()
            .any(|font| font.embedded_path.is_some()));
        assert_eq!(
            document.page_text_objects(0).unwrap()[0].cg_transforms[0].glyphs,
            [0, 37]
        );

        let mut missing_glyph = pdf.clone();
        let cmap = missing_glyph
            .get_object_mut((6, 0))
            .unwrap()
            .as_stream_mut()
            .unwrap();
        let source = std::str::from_utf8(&cmap.content).unwrap();
        cmap.content = source
            .replace("<0041>", "<4E2D>")
            .replace("<0042>", "<6587>")
            .into_bytes();
        let mut bytes = Vec::new();
        missing_glyph.save_to(&mut bytes).unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["中文", "中文"]);
        assert!(document
            .fonts()
            .unwrap()
            .iter()
            .any(|font| font.embedded_path.is_some()));
        assert_eq!(
            document.page_text_objects(0).unwrap()[0].cg_transforms[0].glyphs,
            [36, 37]
        );
    }

    #[test]
    fn imports_explicitly_positioned_type1_text_lines() {
        let bytes = text_pdf(
            b"BT /F1 8 Tf 10 50 Td (One) Tj 0 -12 TD (Two) Tj T* (Three) Tj ET",
            b"Times-Roman",
        );
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["One", "Two", "Three"]);
        let objects = document.page_text_objects(0).unwrap();
        assert!(objects[0].boundary.unwrap()[1] < objects[1].boundary.unwrap()[1]);
        assert!(objects[1].boundary.unwrap()[1] < objects[2].boundary.unwrap()[1]);
    }

    #[test]
    fn imports_type1_text_advance_and_tj_spacing_with_declared_widths() {
        let bytes = text_pdf_with_widths(
            b"BT /F1 10 Tf 10 20 Td (AB) Tj (C) Tj [(D) 120 (E)] TJ ET",
            b"Helvetica",
            Some((b'A', &[600.0; 5])),
        );
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["AB", "C", "DE"]);
        let objects = document.page_text_objects(0).unwrap();
        assert!((objects[1].boundary.unwrap()[0] - 22.0 * MM_PER_PT).abs() < 1e-6);
        assert!((objects[2].boundary.unwrap()[0] - 28.0 * MM_PER_PT).abs() < 1e-6);
        let delta: f64 = objects[2].codes[0]
            .delta_x
            .as_ref()
            .unwrap()
            .parse()
            .unwrap();
        assert!((delta - 4.8 * MM_PER_PT).abs() < 1e-6);
        assert!(document.validate_references().unwrap().is_empty());
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["AB", "C", "DE"]);
        let next_line = text_pdf_with_widths(
            b"BT /F1 10 Tf 10 20 Td 12 TL (AB) Tj T* (C) Tj ET",
            b"Helvetica",
            Some((b'A', &[600.0; 3])),
        );
        let lines = OfdDocument::from_pdf_bytes(&next_line)
            .unwrap()
            .page_text_objects(0)
            .unwrap();
        assert!((lines[1].boundary.unwrap()[0] - 10.0 * MM_PER_PT).abs() < 1e-6);
        let leading_adjustment = text_pdf_with_widths(
            b"BT /F1 10 Tf 10 20 Td [100 (A) 100 (B)] TJ ET",
            b"Helvetica",
            Some((b'A', &[600.0; 2])),
        );
        let shifted = OfdDocument::from_pdf_bytes(&leading_adjustment)
            .unwrap()
            .page_text_objects(0)
            .unwrap();
        assert!((shifted[0].boundary.unwrap()[0] - 9.0 * MM_PER_PT).abs() < 1e-6);
    }

    #[test]
    fn standard14_metrics_position_tj_spacing_without_explicit_widths() {
        let bytes = text_pdf(
            b"BT /F1 10 Tf 10 20 Td 1 Tc 2 Tw [(A ) 100 (B)] TJ (C) Tj ET",
            b"Helvetica",
        );
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["A B", "C"]);
        let objects = document.page_text_objects(0).unwrap();
        let deltas: Vec<f64> = objects[0].codes[0]
            .delta_x
            .as_ref()
            .unwrap()
            .split_whitespace()
            .map(|value| value.parse().unwrap())
            .collect();
        assert!((deltas[0] - 7.67 * MM_PER_PT).abs() < 1e-6);
        assert!((deltas[1] - 4.78 * MM_PER_PT).abs() < 1e-6);
        assert!((objects[1].boundary.unwrap()[0] - 30.12 * MM_PER_PT).abs() < 1e-6);
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["A B", "C"]);
    }

